import { type Hex, parseAbi } from "viem";

// Coin.sol compiled with solc 0.8.30 (default settings). Regenerate from a foundry project
// containing Coin.sol:
//   forge inspect src/Coin.sol:Coin bytecode

/** Creation bytecode; the constructor takes the supply, minted to the deployer. */
export const COIN_BYTECODE: Hex =
  "";

export const coinAbi = parseAbi([
  "constructor(uint256 supply)",
  "function name() view returns (string)",
  "function symbol() view returns (string)",
  "function decimals() view returns (uint8)",
  "function totalSupply() view returns (uint256)",
  "function balanceOf(address) view returns (uint256)",
  "function allowance(address, address) view returns (uint256)",
  "function transfer(address to, uint256 value) returns (bool)",
  "function approve(address spender, uint256 value) returns (bool)",
  "function transferFrom(address from, address to, uint256 value) returns (bool)",
  "event Transfer(address indexed from, address indexed to, uint256 value)",
  "event Approval(address indexed owner, address indexed spender, uint256 value)",
]);
